1392  void Mac::HandleReceivedFrame(Frame *aFrame, otError aError)
  1393  {
  1394      ThreadNetif &netif = GetNetif();
  1395      Address      srcaddr;
  1396      Address      dstaddr;
  1397      PanId        panid;
  1398      Neighbor *   neighbor;
  1399      bool         receive = false;
  1400      otError      error   = aError;
  1401  #if OPENTHREAD_ENABLE_MAC_FILTER
  1402      int8_t rssi = OT_MAC_FILTER_FIXED_RSS_DISABLED;
  1403  #endif // OPENTHREAD_ENABLE_MAC_FILTER
  1404
  1405      mCounters.mRxTotal++;
  1406
  1407      VerifyOrExit(error == OT_ERROR_NONE);
  1408      VerifyOrExit(aFrame != NULL, error = OT_ERROR_NO_FRAME_RECEIVED);
  1409      VerifyOrExit(mEnabled, error = OT_ERROR_INVALID_STATE);
  1410
  1411      // Ensure we have a valid frame before attempting to read any contents of
  1412      // the buffer received from the radio.
  1413      SuccessOrExit(error = aFrame->ValidatePsdu());
  1414
  1415      aFrame->GetSrcAddr(srcaddr);
  1416      aFrame->GetDstAddr(dstaddr);
  1417      neighbor = netif.GetMle().GetNeighbor(srcaddr);
  1418
  1419      // Destination Address Filtering
  1420      switch (dstaddr.GetType())
  1421      {
  1422      case Address::kTypeNone:
  1423          break;
  1424
  1425      case Address::kTypeShort:
  1426          aFrame->GetDstPanId(panid);
  1427          VerifyOrExit((panid == kShortAddrBroadcast || panid == mPanId) &&
  1428                           ((mRxOnWhenIdle && dstaddr.IsBroadcast()) || dstaddr.GetShort() == GetShortAddress()),
  1429                       error = OT_ERROR_DESTINATION_ADDRESS_FILTERED);
  1430
  1431          // Allow  multicasts from neighbor routers if FTD
  1432          if (neighbor == NULL && dstaddr.IsBroadcast() && netif.GetMle().IsFullThreadDevice())
  1433          {
  1434              neighbor = netif.GetMle().GetRxOnlyNeighborRouter(srcaddr);
  1435          }
  1436
  1437          break;
  1438
  1439      case Address::kTypeExtended:
  1440          aFrame->GetDstPanId(panid);
  1441          VerifyOrExit(panid == mPanId && dstaddr.GetExtended() == GetExtAddress(),
  1442                       error = OT_ERROR_DESTINATION_ADDRESS_FILTERED);
  1443          break;
  1444      }
  1445
  1446      // Source Address Filtering
  1447      switch (srcaddr.GetType())
  1448      {
  1449      case Address::kTypeNone:
  1450          break;
  1451
  1452      case Address::kTypeShort:
  1453          otLogDebgMac("Received frame from short address 0x%04x", srcaddr.GetShort());
  1454
  1455          if (neighbor == NULL)
  1456          {
  1457              ExitNow(error = OT_ERROR_UNKNOWN_NEIGHBOR);
  1458          }
  1459
  1460          srcaddr.SetExtended(neighbor->GetExtAddress());
  1461
  1462          // fall through
  1463
  1464      case Address::kTypeExtended:
  1465
  1466          // Duplicate Address Protection
  1467          if (srcaddr.GetExtended() == GetExtAddress())
  1468          {
  1469              ExitNow(error = OT_ERROR_INVALID_SOURCE_ADDRESS);
  1470          }
  1471
  1472  #if OPENTHREAD_ENABLE_MAC_FILTER
  1473
  1474          // Source filter Processing. Check if filtered out by whitelist or blacklist.
  1475          SuccessOrExit(error = mFilter.Apply(srcaddr.GetExtended(), rssi));
  1476
  1477          // override with the rssi in setting
  1478          if (rssi != OT_MAC_FILTER_FIXED_RSS_DISABLED)
  1479          {
  1480              aFrame->SetRssi(rssi);
  1481          }
  1482
  1483  #endif // OPENTHREAD_ENABLE_MAC_FILTER
  1484
  1485          break;
  1486      }
  1487
  1488      // Increment counters
  1489      if (dstaddr.IsBroadcast())
  1490      {
  1491          // Broadcast frame
  1492          mCounters.mRxBroadcast++;
  1493      }
  1494      else
  1495      {
  1496          // Unicast frame
  1497          mCounters.mRxUnicast++;
  1498      }
  1499
  1500      // Security Processing
  1501      error = ProcessReceiveSecurity(*aFrame, srcaddr, neighbor);
  1502
  1503      switch (error)
  1504      {
  1505      case OT_ERROR_DUPLICATED:
  1506
  1507          // Allow a duplicate received frame pass, only if the
  1508          // current operation is `kOperationWaitingForData` (i.e.,
  1509          // the sleepy device is waiting to receive a frame after
  1510          // a data poll ack from parent indicating there is a
  1511          // pending frame for it). This ensures that the sleepy
  1512          // device goes to sleep faster and avoids a data poll
  1513          // timeout.
  1514          //
  1515          // Note that `error` is checked again later after the
  1516          // operation `kOperationWaitingForData` is processed
  1517          // so the duplicate frame will not be passed to next
  1518          // layer (`MeshForwarder`).
  1519
  1520          VerifyOrExit(mOperation == kOperationWaitingForData);
  1521
  1522          // Fall through
  1523
  1524      case OT_ERROR_NONE:
  1525          break;
  1526
  1527      default:
  1528          ExitNow();
  1529      }
  1530
  1531      netif.GetMeshForwarder().GetDataPollManager().CheckFramePending(*aFrame);
  1532
  1533  #if OPENTHREAD_CONFIG_HEADER_IE_SUPPORT
  1534
  1535      if (aFrame->GetVersion() == Frame::kFcfFrameVersion2015)
  1536      {
  1537  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
  1538          ProcessTimeIe(*aFrame);
  1539  #endif
  1540      }
  1541
  1542  #endif // OPENTHREAD_CONFIG_HEADER_IE_SUPPORT
  1543
  1544      if (neighbor != NULL)
  1545      {
  1546  #if OPENTHREAD_ENABLE_MAC_FILTER
  1547
  1548          // make assigned rssi to take effect quickly
  1549          if (rssi != OT_MAC_FILTER_FIXED_RSS_DISABLED)
  1550          {
  1551              neighbor->GetLinkInfo().Clear();
  1552          }
  1553
  1554  #endif // OPENTHREAD_ENABLE_MAC_FILTER
  1555
  1556          neighbor->GetLinkInfo().AddRss(GetNoiseFloor(), aFrame->GetRssi());
  1557
  1558          if (aFrame->GetSecurityEnabled() == true)
  1559          {
  1560              switch (neighbor->GetState())
  1561              {
  1562              case Neighbor::kStateValid:
  1563                  break;
  1564
  1565              case Neighbor::kStateRestored:
  1566              case Neighbor::kStateChildUpdateRequest:
  1567
  1568                  // Only accept a "MAC Data Request" frame from a child being restored.
  1569                  VerifyOrExit(aFrame->IsDataRequestCommand(), error = OT_ERROR_DROP);
  1570                  break;
  1571
  1572              default:
  1573                  ExitNow(error = OT_ERROR_UNKNOWN_NEIGHBOR);
  1574              }
  1575          }
  1576      }
  1577
  1578      switch (mOperation)
  1579      {
  1580      case kOperationActiveScan:
  1581
  1582          if (aFrame->GetType() == Frame::kFcfFrameBeacon)
  1583          {
  1584              mCounters.mRxBeacon++;
  1585              mActiveScanHandler(GetInstance(), aFrame);
  1586              ExitNow();
  1587          }
  1588
  1589          // Fall-through
  1590
  1591      case kOperationEnergyScan:
  1592
  1593          // We can possibly receive a data frame while either active or
  1594          // energy scan is ongoing. We continue to process the frame only
  1595          // if the current scan channel matches `mPanChannel`.
  1596
  1597          VerifyOrExit(mScanChannel == mPanChannel, mCounters.mRxOther++);
  1598          break;
  1599
  1600      case kOperationWaitingForData:
  1601
  1602          if (!dstaddr.IsNone())
  1603          {
  1604              mTimer.Stop();
  1605
  1606  #if OPENTHREAD_CONFIG_STAY_AWAKE_BETWEEN_FRAGMENTS
  1607              if (!mRxOnWhenIdle && !mPromiscuous && aFrame->GetFramePending())
  1608              {
  1609                  mShouldDelaySleep = true;
  1610                  otLogDebgMac("Delay sleep for pending rx");
  1611              }
  1612  #endif
  1613              FinishOperation();
  1614              PerformNextOperation();
  1615          }
  1616
  1617          SuccessOrExit(error);
  1618
  1619          break;
  1620
  1621      default:
  1622          break;
  1623      }
  1624
  1625      switch (aFrame->GetType())
  1626      {
  1627      case Frame::kFcfFrameMacCmd:
  1628          if (HandleMacCommand(*aFrame) == OT_ERROR_DROP)
  1629          {
  1630              ExitNow(error = OT_ERROR_NONE);
  1631          }
  1632
  1633          receive = true;
  1634          break;
  1635
  1636      case Frame::kFcfFrameBeacon:
  1637          mCounters.mRxBeacon++;
  1638          receive = true;
  1639          break;
  1640
  1641      case Frame::kFcfFrameData:
  1642          mCounters.mRxData++;
  1643          receive = true;
  1644          break;
  1645
  1646      default:
  1647          mCounters.mRxOther++;
  1648          break;
  1649      }
  1650
  1651      if (receive)
  1652      {
  1653          otDumpDebgMac("RX", aFrame->GetHeader(), aFrame->GetLength());
  1654          netif.GetMeshForwarder().HandleReceivedFrame(*aFrame);
  1655      }
  1656
  1657  exit:
  1658
  1659      if (error != OT_ERROR_NONE)
  1660      {
  1661          LogFrameRxFailure(aFrame, error);
  1662
  1663          switch (error)
  1664          {
  1665          case OT_ERROR_SECURITY:
  1200      }
  1201
  1202      netif.GetMac().SetPanId(mRestorePanId);
  1203      mScanning = false;
  1204      netif.GetMle().HandleDiscoverComplete();
  1205      mDiscoverTimer.Stop();
  1206  }
