  1208  void MeshForwarder::HandleReceivedFrame(Mac::Frame &aFrame)
  1209  {
  1210      ThreadNetif &    netif = GetNetif();
  1211      otThreadLinkInfo linkInfo;
  1212      Mac::Address     macDest;
  1213      Mac::Address     macSource;
  1214      uint8_t *        payload;
  1215      uint8_t          payloadLength;
  1216      otError          error = OT_ERROR_NONE;
  1217
  1218      if (!mEnabled)
  1219      {
  1220          ExitNow(error = OT_ERROR_INVALID_STATE);
  1221      }
  1222
  1223      SuccessOrExit(error = aFrame.GetSrcAddr(macSource));
  1224      SuccessOrExit(error = aFrame.GetDstAddr(macDest));
  1225
  1226      aFrame.GetSrcPanId(linkInfo.mPanId);
  1227      linkInfo.mChannel      = aFrame.GetChannel();
  1228      linkInfo.mRss          = aFrame.GetRssi();
  1229      linkInfo.mLqi          = aFrame.GetLqi();
  1230      linkInfo.mLinkSecurity = aFrame.GetSecurityEnabled();
  1231  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
  1232      linkInfo.mNetworkTimeOffset = aFrame.GetNetworkTimeOffset();
  1233      linkInfo.mTimeSyncSeq       = aFrame.GetTimeSyncSeq();
  1234  #endif
  1235
  1236      payload       = aFrame.GetPayload();
  1237      payloadLength = aFrame.GetPayloadLength();
  1238
  1239      netif.GetSupervisionListener().UpdateOnReceive(macSource, linkInfo.mLinkSecurity);
  1240
  1241      switch (aFrame.GetType())
  1242      {
  1243      case Mac::Frame::kFcfFrameData:
  1244          if (payloadLength >= sizeof(Lowpan::MeshHeader) &&
  1245              reinterpret_cast<Lowpan::MeshHeader *>(payload)->IsMeshHeader())
  1246          {
  1247  #if OPENTHREAD_FTD
  1248              HandleMesh(payload, payloadLength, macSource, linkInfo);
  1249  #endif
  1250          }
  1251          else if (payloadLength >= sizeof(Lowpan::FragmentHeader) &&
  1252                   reinterpret_cast<Lowpan::FragmentHeader *>(payload)->IsFragmentHeader())
  1253          {
  1254              HandleFragment(payload, payloadLength, macSource, macDest, linkInfo);
  1255          }
  1256          else if (payloadLength >= 1 && Lowpan::Lowpan::IsLowpanHc(payload))
  1257          {
  1258              HandleLowpanHC(payload, payloadLength, macSource, macDest, linkInfo);
  1259          }
  1260          else
  1261          {
  1262              VerifyOrExit(payloadLength == 0, error = OT_ERROR_NOT_LOWPAN_DATA_FRAME);
  1263
  1264              LogFrame("Received empty payload frame", aFrame, OT_ERROR_NONE);
  1265          }
  1266
  1267          break;
  1268
  1269  #if OPENTHREAD_FTD
  1270
  1271      case Mac::Frame::kFcfFrameMacCmd:
  1272      {
  1273          uint8_t commandId;
  1274
  1275          aFrame.GetCommandId(commandId);
  1276
  1277          if (commandId == Mac::Frame::kMacCmdDataRequest)
  1278          {
  1279              HandleDataRequest(macSource, linkInfo);
  1280          }
  1281          else
  1282          {
  1283              error = OT_ERROR_DROP;
  1284          }
  1285
  1286          break;
  1287      }
  1288
  1289  #endif
  1290
  1291      case Mac::Frame::kFcfFrameBeacon:
  1292          break;
  1293
  1294      default:
  1295          error = OT_ERROR_DROP;
  1296          break;
  1297      }
  1298
  1299  exit:
  1300
  1301      if (error != OT_ERROR_NONE)
  1302      {
  1303          LogFrame("Dropping rx frame", aFrame, error);
  1304      }
  1305  }
